/** Hospital service prices (lab prices live in the lab catalogue) — GET /api/v1/finance/service-catalog (who may call: any logged-in user). */
export function serviceCatalog(query?: { category?: string | null }): Promise<ServiceListItemOut[]> {
  return api<ServiceListItemOut[]>("GET", withQuery(`/finance/service-catalog`, query), undefined);
}

/** Add a priced service — POST /api/v1/finance/service-catalog (who may call: holders of finance.service_catalog.manage). */
export function addService(body: ServiceIn): Promise<ServiceOut> {
  return api<ServiceOut>("POST", `/finance/service-catalog`, body, { idempotent: true });
}

/** Change a price / deactivate (versioned history kept) — PATCH /api/v1/finance/service-catalog/{service_id} (who may call: holders of finance.service_catalog.manage). */
export function patchService(service_id: number, body: ServicePatch): Promise<ServiceOut> {
  return api<ServiceOut>("PATCH", `/finance/service-catalog/${service_id}`, body);
}

